/** Everything the markup binds to, for one position in the loop. */
export function values(p) {
  // p is the argument.
  function lin(k) {
    if (p <= k[0][0]) return k[0][1];
    for (var i = 1; i < k.length; i++) if (p <= k[i][0]) { var a = k[i-1], b = k[i], f = (p - a[0]) / (b[0] - a[0]); f = 1 - Math.pow(1 - f, 3); return a[1] + (b[1] - a[1]) * f; }
    return k[k.length-1][1];
  }
  var out = p < 94 ? 1 : Math.max(0, 1 - (p - 94) / 6);
  var v = {};
  function phases(ph) { for (var i = 0; i < ph.length; i++) { v['on'+i] = (p >= ph[i][0] && p < ph[i][1]) ? 1 : 0; v['done'+i] = (p >= ph[i][1] && p < 97) ? out : 0; } }

  var D = {"N": 12, "NX": 6, "NT": 3};
  phases([[0,14],[14,28],[28,42],[42,78]]);
  v.xO = lin([[0,0],[3,1]]) * out; v.xT = 'translateX(' + lin([[0,24],[3,0]]).toFixed(1) + 'px)';
  for (var i = 0; i < D.NX; i++) v['x'+i] = (p >= 3 + i * 1.5 ? 1 : 0);
  v.rmO = lin([[14,0],[18,1]]) * out; v.wO = lin([[16,0],[22,1]]) * out;
  v.tyO = lin([[28,0],[31,1]]) * out;
  for (var i = 0; i < D.NT; i++) v['ty'+i] = (p >= 31 + i * 3 ? 1 : 0);
  for (var i = 0; i < D.N; i++) {
    var t = 42 + i * 2.6, f = lin([[t,0],[t+2,1]]);
    v['c'+i] = 'opacity: ' + ((f > 0.01 ? 1 : 0) * out) + '; transform: translateY(' + (-26 * (1 - f)).toFixed(1) + 'px);';
    v['tg'+i] = (p >= t + 2 && p < 97) ? out : 0;
  }
  v.fin = (p >= 76 && p < 97) ? out : 0;

  return { v: v };}

const card = { id, title, width, height, loopMs, attrs, stage, markup, values };
export default card;
